#!/usr/bin/env python3
"""Patch 100: Quality > Final check keeps the zip it is given and can run from saved admin batches, so it is uploaded once. Needs patch 99. Careerflow platform enhancements. Run from the repo root (the folder that holds backend/ and frontend/).
Safe to run twice: files already applied are skipped."""
import os, sys, zlib, base64
sys.stdout.reconfigure(errors='replace')
NEW = {'backend/app/services/admin_upload.py': '', 'backend/app/api/v1/routes/admin_upload.py': '', 'frontend/src/api/adminUpload.ts': ''}
MOD = {'frontend/src/components/enh/FinalCheck.tsx': [("import { ask } from '@/lib/confirm'", "import { ask } from '@/lib/confirm'\nimport { adminUploadApi } from '@/api/adminUpload'"), ("  const [file, setFile] = useState<File | null>(null)\n  const [busy, setBusy] = useState<'check' | 'apply' | 'download' | ''>('')", "  const [file, setFile] = useState<File | null>(null)\n  // Saved admin batches: the zip is kept the first time, so it never has to be uploaded again.\n  const [batches, setBatches] = useState<{ batch_id: string; label: string; created_at: string; copies: any[] }[]>([])\n  const [keep, setKeep] = useState(true)\n  const [fromSaved, setFromSaved] = useState('')\n  const [inputKey, setInputKey] = useState(0)\n  const savedFile = useRef<File | null>(null)\n  useEffect(() => { adminUploadApi.library().then(r => setBatches(r.batches)).catch(() => {}) }, [])\n  const useSaved = async (id: string) => {\n    setFromSaved(id)\n    if (!id) return\n    try {\n      const blob = await adminUploadApi.key(id)\n      const label = id === 'latest' ? 'latest saved copies' : (batches.find(b => b.batch_id === id)?.label ?? 'saved batch')\n      setFile(new File([blob], `${label}.json`, { type: 'application/json' })); setRes(null); setDec({}); setSub(null); setInputKey(k => k + 1)\n    } catch (e) { setFromSaved(''); toast.error(err(e, 'Nothing is saved for that batch')) }\n  }\n  const [busy, setBusy] = useState<'check' | 'apply' | 'download' | ''>('')"), ('      const r = await qualityApi.answerKey(file, { apply, projectId, sourceId, decisions: dec })\n      setRes(r)\n', "      const r = await qualityApi.answerKey(file, { apply, projectId, sourceId, decisions: dec })\n      setRes(r)\n      if (!apply && keep && !fromSaved && batches !== null && savedFile.current !== file) {\n        savedFile.current = file\n        adminUploadApi.saveKey(file, projectId, sourceId).then(s => {\n          if (s.saved) toast.success(`Kept a private copy for ${s.saved} source${s.saved === 1 ? '' : 's'}. You will not need to upload it again.`)\n          adminUploadApi.library().then(x => setBatches(x.batches)).catch(() => {})\n        }).catch(() => {})\n      }\n"), ('<input type="file" accept=".zip,.json" onChange={e => { setFile(e.target.files?.[0] ?? null); setRes(null); setDec({}); setSub(null) }} aria-label="Final records file"', '<input key={inputKey} type="file" accept=".zip,.json" onChange={e => { setFile(e.target.files?.[0] ?? null); setFromSaved(\'\'); setRes(null); setDec({}); setSub(null) }} aria-label="Final records file"'), ('        {sourceId && <p className="text-xs text-gray-500 mt-2 mb-0">A single list of records will be checked against the source picked above.</p>}', '        {batches.length > 0 && (\n          <div className="flex items-center gap-3 flex-wrap mt-3 text-sm">\n            <label className="text-gray-600" htmlFor="saved-batch">Or use what you saved before</label>\n            <select id="saved-batch" value={fromSaved} onChange={e => useSaved(e.target.value)} className="border border-gray-200 rounded-lg px-2.5 py-1.5 bg-white text-gray-900 max-w-[22rem]">\n              <option value="">Choose a saved batch…</option>\n              <option value="latest">The newest saved copy of each source</option>\n              {batches.map(b => <option key={b.batch_id} value={b.batch_id}>{b.label} · {new Date(b.created_at).toLocaleDateString()} · {b.copies.length} sources</option>)}\n            </select>\n          </div>\n        )}\n        {!fromSaved && <label className="flex items-center gap-2 text-xs text-gray-600 mt-2"><input type="checkbox" checked={keep} onChange={e => setKeep(e.target.checked)} /> Keep a private copy for next time. Only admins can see it, and it is saved by source name.</label>}\n        {sourceId && <p className="text-xs text-gray-500 mt-2 mb-0">A single list of records will be checked against the source picked above.</p>}')]}
root = os.getcwd()
if not (os.path.isdir(os.path.join(root, 'backend')) and os.path.isdir(os.path.join(root, 'frontend'))):
    sys.exit('Run this from the repo root (the folder containing backend and frontend).')
def rd(p): return open(p, encoding='utf-8', newline='').read()
done = skipped = 0; bad = []
for rel, hunks in MOD.items():
    p = os.path.join(root, rel)
    if not os.path.exists(p): bad.append(rel + ' (missing)'); continue
    raw = rd(p); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n'); changed = False
    for old, new in hunks:
        if new in t and not (new in old and new != old): continue
        elif t.count(old) == 1: t = t.replace(old, new); changed = True
        elif new in t: continue
        else: bad.append(rel + ' (a section does not match; file differs from expected version)'); break
    else:
        if changed:
            open(p, 'w', encoding='utf-8', newline='').write(t.replace('\n', '\r\n') if crlf else t); done += 1; print('updated ', rel)
        else: skipped += 1
for rel, blob in NEW.items():
    p = os.path.join(root, rel); data = zlib.decompress(base64.b64decode(blob))
    if os.path.exists(p) and open(p, 'rb').read() == data: skipped += 1; continue
    os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(data); done += 1; print('wrote   ', rel)
print(f'\n{done} changed, {skipped} already applied.')
if bad:
    print('\nPROBLEMS:'); [print(' -', b) for b in bad]; sys.exit(1)
